// Amount before rounding. `discount` is the customer's discount rate (0.1 = 10%),
// applied once. Carts with 10 or more lines then get an extra 5% bulk discount,
// also applied once.
export function amount(items, discount = 0) {
  const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0);
  const bulk = items.length >= 10 ? 0.05 : 0;
  const exact = subtotal * (1 - discount) * (1 - bulk);
  // Drop binary floating-point noise (e.g. 2150 * 0.94 = 2020.9999999999998)
  // so that callers round the amount that was meant, not the noise.
  return Math.round(exact * 1e6) / 1e6;
}

// Cart total. Fractions below one unit are truncated.
export function total(items, discount = 0) {
  return Math.floor(amount(items, discount));
}

export function itemCount(items) {
  return items.reduce((n, item) => n + item.qty, 0);
}

